ax[-1].set_xlabel('Time')
fig1.suptitle('Hemodynamic lability: rolling medians and IQR (30-minute window)', y=0.995)
fig1.tight_layout(rect=[0, 0, 1, 0.98])
save_plot('hemodynamic_rolling_lability.png', fig=fig1)
fig2, ax2 = plt.subplots(2, 1, sharex=True, figsize=(12, 6))
if cluster_ok and t_used.size > 0:
    ax2[0].plot(t_used, labels_ord, drawstyle='steps-post', color='tab:blue', linewidth=2)
    ax2[0].set_yticks(np.arange(k))
    ax2[0].set_yticklabels([f'State {i}' for i in range(k)])
    ax2[0].set_ylabel('Clustered state')
    ax2[1].bar(np.arange(k), occ_ord * 100.0, color='tab:gray')
    ax2[1].set_xticks(np.arange(k))
    ax2[1].set_xticklabels([f'State {i}' for i in range(k)])
    ax2[1].set_ylabel('Occupancy (%)')
    ax2[1].set_ylim(0, max(5.0, float(np.max(occ_ord) * 100.0) * 1.15))
    for i in range(k):
        ax2[1].text(i, occ_ord[i] * 100.0 + 0.5, f'{occ_ord[i] * 100.0:.1f}%', ha='center', va='bottom', fontsize=9)
    fig2.suptitle('K-means hemodynamic states (SBP, DBP, PP, HR, SI)', y=0.995)
    fig2.tight_layout(rect=[0, 0, 1, 0.98])
else:
    ax2[0].text(0.01, 0.6, 'Insufficient aligned data for clustering/state plot', transform=ax2[0].transAxes)
    ax2[0].set_axis_off()
    ax2[1].set_axis_off()
    fig2.tight_layout()
save_plot('hemodynamic_state_time_and_occupancy.png', fig=fig2)
fig3, ax3 = plt.subplots(1, 1, figsize=(8, 7))
if cluster_ok and X_used_raw.shape[0] > 2:
    palette = sns.color_palette('Set2', n_colors=k)
    for s in range(k):
        m = labels_ord == s
        if np.any(m):
            ax3.scatter(X_used_raw[m, 0], X_used_raw[m, 1], s=35, alpha=0.75, color=palette[s], label=f'State {s}')
    for i in range(1, X_used_raw.shape[0]):
        x0, y0 = (X_used_raw[i - 1, 0], X_used_raw[i - 1, 1])
        x1, y1 = (X_used_raw[i, 0], X_used_raw[i, 1])
        if not (np.isfinite(x0) and np.isfinite(y0) and np.isfinite(x1) and np.isfinite(y1)):
            continue
        changed = labels_ord[i] != labels_ord[i - 1]
        ax3.annotate('', xy=(x1, y1), xytext=(x0, y0), arrowprops=dict(arrowstyle='->', color='k' if changed else '0.6', lw=1.2 if changed else 0.8, alpha=0.55 if changed else 0.18))
    for s in range(k):
        c = centers_raw_ord[s]
        ax3.scatter(c[0], c[1], s=160, marker='X', color=palette[s], edgecolor='k', linewidth=1.0, zorder=5)
    ax3.set_xlabel('SBP (mmHg)')
    ax3.set_ylabel('DBP (mmHg)')
    ax3.set_title('Phase plot (SBP vs DBP) with time-ordered transitions and clustered states')
    ax3.legend(loc='best', fontsize=9)
    ax3.grid(True, alpha=0.25)
else:
    ax3.text(0.01, 0.6, 'Insufficient aligned data for phase plot', transform=ax3.transAxes)
    ax3.set_axis_off()
fig3.tight_layout()
save_plot('hemodynamic_phase_plot_with_transitions.png', fig=fig3)
result = {'inputs': {'age_years': int(age), 'gender': str(gender), 'window_minutes': float(rolling_window_min), 'kmeans_k': int(k), 'n_sbp_points_total': int(t_sbp.size), 'n_dbp_points_total': int(t_dbp.size), 'n_hr_points_total': int(t_hr.size), 'n_aligned_points_used_for_clustering': int(X_used_raw.shape[0])}, 'provided_metrics_used': {'shock_index': float(shock_index), 'map_value': float(map_value), 'pulse_pressure': float(pulse_pressure), 'qsofa_score': int(qsofa_score), 'sirs': int(sirs)}, 'rolling_bp_lability': {'sbp': {'rolling_median_last_mmHg': float(sbp_roll['median'][-1]) if sbp_roll['median'].size > 0 and np.isfinite(sbp_roll['median'][-1]) else None, 'rolling_iqr_last_mmHg': float(sbp_roll['iqr'][-1]) if sbp_roll['iqr'].size > 0 and np.isfinite(sbp_roll['iqr'][-1]) else None, 'rolling_std_last_mmHg': float(sbp_roll['std'][-1]) if sbp_roll['std'].size > 0 and np.isfinite(sbp_roll['std'][-1]) else None}, 'dbp': {'rolling_median_last_mmHg': float(dbp_roll['median'][-1]) if dbp_roll['median'].size > 0 and np.isfinite(dbp_roll['median'][-1]) else None, 'rolling_iqr_last_mmHg': float(dbp_roll['iqr'][-1]) if dbp_roll['iqr'].size > 0 and np.isfinite(dbp_roll['iqr'][-1]) else None, 'rolling_std_last_mmHg': float(dbp_roll['std'][-1]) if dbp_roll['std'].size > 0 and np.isfinite(dbp_roll['std'][-1]) else None}, 'derived': {'pp_rolling_median_last_mmHg': float(pp_roll['median'][-1]) if pp_roll['median'].size > 0 and np.isfinite(pp_roll['median'][-1]) else None, 'si_rolling_median_last': float(si_roll['median'][-1]) if si_roll['median'].size > 0 and np.isfinite(si_roll['median'][-1]) else None}}, 'kmeans_state_model': {'fit_success': bool(cluster_ok), 'k': int(k), 'centers_raw_by_state_ordered_by_sbp': [{'state': int(i), 'center': {'SBP_mmHg': float(centers_raw_ord[i, 0]), 'DBP_mmHg': float(centers_raw_ord[i, 1]), 'PP_mmHg': float(centers_raw_ord[i, 2]), 'HR_bpm': float(centers_raw_ord[i, 3]), 'SI': float(centers_raw_ord[i, 4])}, 'occupancy_pct': float(occ_ord[i] * 100.0)} for i in range(k)] if cluster_ok else [], 'n_transitions': int(np.sum(labels_ord[1:] != labels_ord[:-1])) if cluster_ok and labels_ord.size > 1 else 0, 'inertia_scaled_space': float(inertia) if cluster_ok and inertia is not None else None}, 'plots': {'hemodynamic_rolling_lability': 'hemodynamic_rolling_lability.png', 'hemodynamic_state_time_and_occupancy': 'hemodynamic_state_time_and_occupancy.png', 'hemodynamic_phase_plot_with_transitions': 'hemodynamic_phase_plot_with_transitions.png'}}
if cluster_ok and centers_raw_ord.shape[0] == k:
    highest_si_state = int(np.nanargmax(centers_raw_ord[:, 4]))
    interpretation = f'Hemodynamic k-means (k={k}) identified {result['kmeans_state_model']['n_transitions']} state transitions; the lowest-SBP state center is SBP {centers_raw_ord[0, 0]:.0f} mmHg / DBP {centers_raw_ord[0, 1]:.0f} mmHg (PP {centers_raw_ord[0, 2]:.0f} mmHg, SI {centers_raw_ord[0, 4]:.2f}) with occupancy {occ_ord[0] * 100.0:.1f}%, and the highest-SI state is State {highest_si_state} (SI {centers_raw_ord[highest_si_state, 4]:.2f}) with occupancy {occ_ord[highest_si_state] * 100.0:.1f}%, supporting intermittent hypotensive/high-SI physiology on a background elevated shock index ({shock_index:.2f}).'
else:
    interpretation = f'Rolling lability metrics were computed where possible, but there were insufficient aligned SBP/DBP/HR datapoints to reliably cluster hemodynamic states; overall shock index remains elevated at {shock_index:.2f} with MAP {map_value:.1f} mmHg and pulse pressure {pulse_pressure:.1f} mmHg.'

plt.close()